import { describe, it, expect, beforeAll } from 'vitest'
import { mkdtemp, readdir, readFile, rm } from 'node:fs/promises'
import { readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, relative } from 'node:path'
import { buildDesignSystem, DS_PROJECT_DIR, dsProjectAvailable } from '../scripts/ds-tokens.mjs'
import { buildDsIcons } from '../scripts/ds-icons.mjs'

// Gate of ADR-070 dec. 1: the Design System tokens.json (generated by `npm run tokens`) compiles,
// in the Claude Design System type, to EXACTLY the public CSS variables of the client — so a canvas
// with the DS installed writes `var(--space-20)` like the client does. Unit, no stack.
//
// What the type compiles (its format.md): `--<name>` for every token of every `{"tokens":[…]}`
// family (color and shadow per theme), `--font-<key>` per `type.families` key; `motion` is ignored.

type Token = { name: string; value: unknown; usage: string }
type Style = { name: string; fontSize: string; lineHeight: number; fontWeight: number }
type Ds = Record<string, unknown> & {
  color: { themes: Array<{ id: string }>; tokens: Token[] }
  type: { families: Record<string, string>; groups: Array<{ family: string; styles: Style[] }> }
}

const CSS = readFileSync(join(__dirname, '..', 'src', 'ui', 'tokens', 'tokens.css'), 'utf8')
const TS = readFileSync(join(__dirname, '..', 'src', 'ui', 'tokens', 'tokens.ts'), 'utf8')
// Read in beforeAll, not at collection: describe.skipIf does not guard the describe body, and a
// tree without design/ (the public source) has no tokens.json to read.
let DS: Ds

const NAME = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/

function cssNames(): Set<string> {
  return new Set([...CSS.matchAll(/^\s*--([a-z0-9-]+):/gm)].map((m) => m[1] as string))
}

// Every family the type would compile, by family key → its tokens.
function tokenFamilies(ds: Ds): Array<[string, Token[]]> {
  return Object.entries(ds)
    .filter(([k, v]) => k !== 'type' && k !== 'motion' && Array.isArray((v as { tokens?: unknown })?.tokens))
    .map(([k, v]) => [k, (v as { tokens: Token[] }).tokens])
}

function dsNames(ds: Ds): string[] {
  return [
    ...tokenFamilies(ds).flatMap(([, ts]) => ts.map((t) => t.name)),
    ...Object.keys(ds.type.families).map((k) => `font-${k}`),
  ]
}

const diff = (a: Set<string>, b: Set<string>) => [...a].filter((x) => !b.has(x)).sort()

async function listFiles(dir: string): Promise<string[]> {
  const out: string[] = []
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = join(dir, e.name)
    if (e.isDirectory()) out.push(...(await listFiles(p)))
    else out.push(p)
  }
  return out.sort()
}

async function snapshot(dir: string): Promise<Map<string, Buffer>> {
  const files = await listFiles(dir)
  return new Map(await Promise.all(files.map(async (f) => [relative(dir, f), await readFile(f)] as const)))
}

describe.skipIf(!dsProjectAvailable())('DS tokens.json ↔ client public tokens (ADR-070 dec. 1)', () => {
  beforeAll(() => {
    DS = JSON.parse(readFileSync(join(DS_PROJECT_DIR, 'tokens.json'), 'utf8')) as Ds
  })

  it('witness: design/system present', () => {
    console.log('ds-tokens: design/system present')
    expect(dsProjectAvailable()).toBe(true)
  })

  it('(a–c) compiles to exactly the public names of tokens.css, both ways', () => {
    const css = cssNames()
    const ds = new Set(dsNames(DS))
    expect(css.size).toBeGreaterThan(0)
    expect({ missingInDs: diff(css, ds), extraInDs: diff(ds, css) }).toEqual({ missingInDs: [], extraInDs: [] })
  })

  it('(d) color and shadow values are literals: no var(), no color-mix(), no named color', () => {
    const themes = DS.color.themes.map((t) => t.id)
    expect(themes[0]).toBe('light')
    const bad: string[] = []
    const shadow = (DS.shadow as { tokens: Token[] }).tokens
    for (const [fam, list] of [['color', DS.color.tokens], ['shadow', shadow]] as const) {
      for (const t of list) {
        const values = typeof t.value === 'string' ? [t.value] : themes.map((id) => (t.value as Record<string, string>)[id])
        for (const v of values) {
          if (typeof v !== 'string' || /var\(|color-mix\(/.test(v)) bad.push(`${fam}:${t.name}=${String(v)}`)
          else if (fam === 'color' && !/^(#[0-9a-f]{3,8}|(rgba?|hsla?|oklch)\([0-9., %/]+\))$/.test(v)) {
            bad.push(`${fam}:${t.name}=${v}`)
          }
        }
      }
    }
    expect(bad).toEqual([])
  })

  it('(e) names match the type grammar and are unique across families', () => {
    const names = dsNames(DS)
    expect(names.filter((n) => !NAME.test(n))).toEqual([])
    expect(names.filter((n, i) => names.indexOf(n) !== i)).toEqual([])
  })

  it('(f) the generator is deterministic and the committed DS is current', async () => {
    const a = await mkdtemp(join(tmpdir(), 'ds-a-'))
    const b = await mkdtemp(join(tmpdir(), 'ds-b-'))
    try {
      for (const dir of [a, b]) {
        await buildDesignSystem(dir)
        await buildDsIcons(dir)
      }
      const [sa, sb, committed] = await Promise.all([snapshot(a), snapshot(b), snapshot(DS_PROJECT_DIR)])
      expect([...sa.keys()]).toEqual([...sb.keys()])
      for (const [k, v] of sa) expect(v.equals(sb.get(k) as Buffer), k).toBe(true)
      // Stale = someone changed the DTCG source, styles.css weights, fonts or icons without
      // re-running `npm run tokens`.
      expect([...committed.keys()]).toEqual([...sa.keys()])
      for (const [k, v] of sa) expect(v.equals(committed.get(k) as Buffer), `stale: ${k}`).toBe(true)
    } finally {
      await rm(a, { recursive: true, force: true })
      await rm(b, { recursive: true, force: true })
    }
  })

  it('(g) type.groups carry exactly the text styles ratified by the owner (20/Out/2026)', () => {
    const styles = DS.type.groups.flatMap((g) =>
      g.styles.map(({ name, fontSize, lineHeight, fontWeight }) => ({ name, family: g.family, fontSize, lineHeight, fontWeight })),
    )
    expect(styles).toEqual([
      { name: 'display', family: 'family-sans', fontSize: '22px', lineHeight: 1.25, fontWeight: 500 },
      { name: 'title', family: 'family-sans', fontSize: '16px', lineHeight: 1.3, fontWeight: 500 },
      { name: 'body', family: 'family-sans', fontSize: '15px', lineHeight: 1.55, fontWeight: 400 },
      { name: 'ui', family: 'family-sans', fontSize: '14px', lineHeight: 1.4, fontWeight: 400 },
      { name: 'meta', family: 'family-sans', fontSize: '12px', lineHeight: 1.35, fontWeight: 400 },
      { name: 'mono', family: 'family-mono', fontSize: '13px', lineHeight: 1.5, fontWeight: 400 },
    ])
  })

  it('(h) the font.style composites stay out of the client outputs', () => {
    expect(CSS).not.toMatch(/font-style-/)
    expect(TS).not.toMatch(/font-style-|\bstyle:/)
  })
})
